/**
 * React Component Adapter 테스트
 * ReactComponentAdapter의 모든 기능을 검증
 */

const ReactComponentAdapter = require('./react-adapter');

let testsPassed = 0;
let testsFailed = 0;

// 테스트 유틸리티
function assertEqual(actual, expected, message) {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    console.error(`❌ ${message}`);
    console.error(`   Expected: ${JSON.stringify(expected)}`);
    console.error(`   Actual: ${JSON.stringify(actual)}`);
    testsFailed++;
    throw new Error(`Assertion failed: ${message}`);
  }
}

function assertTrue(condition, message) {
  if (!condition) {
    console.error(`❌ ${message}`);
    testsFailed++;
    throw new Error(`Assertion failed: ${message}`);
  }
}

function assertContains(str, substring, message) {
  if (!str.includes(substring)) {
    console.error(`❌ ${message}`);
    console.error(`   Expected substring: ${substring}`);
    console.error(`   In string (first 100 chars): ${str.substring(0, 100)}...`);
    testsFailed++;
    throw new Error(`Assertion failed: ${message}`);
  }
}

// 테스트 케이스
console.log('\n╔════════════════════════════════════════════╗');
console.log('║  React Component Adapter 테스트         ║');
console.log('╚════════════════════════════════════════════╝\n');

// Test 1: PropTypes 생성
try {
  console.log('📝 Test 1: PropTypes 코드 생성');
  const component = {
    name: 'Button',
    props: {
      label: { type: 'string', required: true },
      type: { type: 'string', default: 'primary' },
      disabled: { type: 'bool' },
    },
  };

  const adapter = new ReactComponentAdapter(component);
  const propTypes = adapter.getPropTypes();

  assertTrue('label' in propTypes, 'label PropType이 있어야 함');
  assertTrue(propTypes.label.includes('PropTypes.string'), 'label은 PropTypes.string');
  assertTrue(propTypes.label.includes('isRequired'), 'label은 필수');
  assertTrue(propTypes.type.includes('PropTypes.string'), 'type은 PropTypes.string');
  assertContains(propTypes.disabled, 'PropTypes.bool', 'disabled는 PropTypes.bool');

  console.log('✅ PropTypes 생성 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 2: 기본값 설정
try {
  console.log('📝 Test 2: 기본값 (defaultProps) 설정');
  const component = {
    name: 'Card',
    props: {
      title: { type: 'string', default: 'Untitled' },
      count: { type: 'number', default: 0 },
      active: { type: 'bool', default: true },
    },
  };

  const adapter = new ReactComponentAdapter(component);
  const defaultProps = adapter.getDefaultProps();

  assertEqual(defaultProps.title, 'Untitled', 'title 기본값 확인');
  assertEqual(defaultProps.count, 0, 'count 기본값 확인');
  assertEqual(defaultProps.active, true, 'active 기본값 확인');

  console.log('✅ 기본값 설정 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 3: JSX 생성
try {
  console.log('📝 Test 3: JSX 마크업 변환');
  const component = {
    name: 'Button',
    markup: '<button onclick="handleClick">{label}</button>',
  };

  const adapter = new ReactComponentAdapter(component);
  const jsx = adapter.getJSX();

  assertTrue(jsx.includes('onClick'), 'onclick → onClick 변환');
  assertTrue(jsx.includes('{label}'), 'Props 바인딩 유지');

  console.log('✅ JSX 생성 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 4: 조건부 렌더링 변환
try {
  console.log('📝 Test 4: 조건부 렌더링 (if) 변환');
  const component = {
    name: 'Card',
    markup: `
      <div>
        if showFooter { <footer>Footer</footer> }
      </div>
    `,
  };

  const adapter = new ReactComponentAdapter(component);
  const jsx = adapter.getJSX();

  assertTrue(jsx.includes('&&'), 'if는 && 연산자로 변환');
  assertTrue(jsx.includes('showFooter'), 'showFooter 조건 유지');

  console.log('✅ 조건부 렌더링 변환 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 5: 반복 렌더링 변환
try {
  console.log('📝 Test 5: 반복 렌더링 (for) 변환');
  const component = {
    name: 'List',
    markup: `
      <div>
        for item in items { <li>{item}</li> }
      </div>
    `,
  };

  const adapter = new ReactComponentAdapter(component);
  const jsx = adapter.getJSX();

  assertTrue(jsx.includes('.map'), 'for는 .map()으로 변환');
  assertTrue(jsx.includes('key={'), 'key prop이 추가되어야 함');

  console.log('✅ 반복 렌더링 변환 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 6: React 컴포넌트 코드 생성
try {
  console.log('📝 Test 6: React 함수형 컴포넌트 생성');
  const component = {
    name: 'Button',
    props: {
      label: { type: 'string' },
    },
    markup: '<button>{label}</button>',
    style: '.btn { padding: 10px; }',
    script: '',
  };

  const adapter = new ReactComponentAdapter(component);
  const code = adapter.toReactComponent();

  assertContains(code, 'import React', 'React import 포함');
  assertContains(code, `const ${component.name} = ({`, '컴포넌트 선언');
  assertContains(code, 'export default', 'export default 포함');
  assertContains(code, 'propTypes', 'PropTypes 정의 포함');
  assertContains(code, 'defaultProps', 'defaultProps 정의 포함');

  console.log('✅ React 컴포넌트 코드 생성 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 7: TypeScript 버전 생성
try {
  console.log('📝 Test 7: TypeScript React 컴포넌트 생성');
  const component = {
    name: 'Card',
    props: {
      title: { type: 'string', required: true },
      count: { type: 'number' },
    },
    markup: '<div>{title}: {count}</div>',
    script: '',
  };

  const adapter = new ReactComponentAdapter(component);
  const tsCode = adapter.toReactComponentTS();

  assertContains(tsCode, 'interface', 'TypeScript 인터페이스 포함');
  assertContains(tsCode, `${component.name}Props`, 'Props 인터페이스 포함');
  assertContains(tsCode, 'string', 'string 타입');
  assertContains(tsCode, 'number', 'number 타입');

  console.log('✅ TypeScript React 컴포넌트 생성 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 8: 인라인 스타일 변환
try {
  console.log('📝 Test 8: CSS → 인라인 스타일 변환');
  const component = {
    name: 'Button',
    style: '.btn { padding: 10px; background-color: #007bff; }',
    props: {},
    markup: '',
  };

  const adapter = new ReactComponentAdapter(component);
  const inlineStyles = adapter.getInlineStyles();

  assertTrue('.btn' in inlineStyles, '.btn 스타일 존재');
  assertTrue('padding' in inlineStyles['.btn'], 'padding 속성 있음');
  assertTrue('backgroundColor' in inlineStyles['.btn'], 'camelCase 변환됨');

  console.log('✅ 인라인 스타일 변환 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 9: 호환성 검사
try {
  console.log('📝 Test 9: 호환성 검사');
  const component = {
    name: 'Button',
    props: {
      label: { type: 'string' },
    },
    markup: '<button>{label}</button>',
    style: '',
    script: '',
  };

  const adapter = new ReactComponentAdapter(component);
  const compatibility = adapter.checkCompatibility();

  assertEqual(compatibility.compatible, true, '유효한 컴포넌트는 호환 가능');
  assertEqual(compatibility.issues.length, 0, 'issues 없음');
  assertTrue('info' in compatibility, 'info 객체 포함');

  console.log('✅ 호환성 검사 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 10: 마이그레이션 가이드 및 추가 기능
try {
  console.log('📝 Test 10: 마이그레이션 가이드 + Storybook + Jest');
  const component = {
    name: 'Counter',
    props: {
      initial: { type: 'number', default: 0 },
    },
    markup: '<div>{count}</div>',
    style: '',
    script: 'let count = 0;',
  };

  const adapter = new ReactComponentAdapter(component);

  // 마이그레이션 가이드
  const guide = adapter.getMigrationGuide();
  assertContains(guide, 'Props 인터페이스', '마이그레이션 가이드 포함');

  // Storybook 스토리
  const story = adapter.getStorybookStory();
  assertContains(story, 'export default', 'Storybook default export');
  assertContains(story, '@storybook/react', 'Storybook 임포트');

  // Jest 테스트
  const testCode = adapter.getTestCode();
  assertContains(testCode, 'describe', 'Jest describe 블록');
  assertContains(testCode, 'render', 'render 함수');
  assertContains(testCode, 'expect', 'expect 함수');

  console.log('✅ 마이그레이션 가이드 + 테스트 코드 생성 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// 최종 보고서
console.log('╔════════════════════════════════════════════╗');
console.log(`║  Test 결과: ${testsPassed}/10 통과              ║`);
console.log('╚════════════════════════════════════════════╝\n');

if (testsFailed === 0) {
  console.log('🎉 모든 테스트 통과!\n');
  process.exit(0);
} else {
  console.log(`❌ ${testsFailed}개 테스트 실패\n`);
  process.exit(1);
}

