   * Computed Property 값 가져오기
   * @param {string} name - 컴퓨티드 프로퍼티 이름
   * @returns {*} 계산된 값
   */
  getComputed(name) {
    const getter = this.computedProperties.get(name);
    if (!getter) {
      console.warn(`Computed property "${name}" not found`);
      return undefined;
    }
    return getter(this.state);
  }

