/**
 * Router (라우팅 시스템)
 * FreeLang Light SPA 라우팅
 *
 * 기능:
 * - 동적 라우트 정의 및 매칭
 * - 매개변수 추출
 * - 히스토리 관리
 * - 라우트 가드
 * - 리다이렉트
 * - Lazy Loading
 */

class Router {
  constructor(routes = [], options = {}) {
    this.routes = routes;
    this.currentRoute = null;
    this.history = [];
    this.listeners = new Set();
    this.guards = new Map();
    this.middleware = [];
    this.notFoundHandler = options.notFoundHandler || null;
    this.errorHandler = options.errorHandler || null;
    this.baseUrl = options.baseUrl || '/';
    this.mode = options.mode || 'hash'; // 'hash' or 'history'
    this.scrollBehavior = options.scrollBehavior || null;
    this.lazyLoadCache = new Map();

    // 초기 라우트 로드
    this._initializeRouting();
  }

  /**
   * 라우팅 초기화
   * @private
   */
  _initializeRouting() {
    // 초기 URL 파싱
    const path = this._getCurrentPath();
    this.navigate(path);

    // 히스토리 변경 감지
    if (this.mode === 'hash') {
      window.addEventListener('hashchange', () => {
        const path = this._getCurrentPath();
        this.navigate(path);
      });
    } else {
      window.addEventListener('popstate', () => {
        const path = this._getCurrentPath();
        this.navigate(path);
      });
    }
  }

  /**
   * 현재 경로 가져오기
   * @private
   * @returns {string} 현재 경로
   */
  _getCurrentPath() {
    if (this.mode === 'hash') {
      return window.location.hash.slice(1) || '/';
    } else {
      return window.location.pathname;
    }
  }

  /**
   * 라우트 등록
   * @param {string} path - 라우트 경로 (예: "/user/:id")
   * @param {Object} component - 컴포넌트
   * @param {Object} meta - 메타 정보
   */
  registerRoute(path, component, meta = {}) {
    this.routes.push({
      path,
      component,
      meta,
      regex: this._pathToRegex(path),
      params: this._extractParamNames(path),
    });
  }

  /**
   * 경로를 정규식으로 변환
   * @private
   * @param {string} path - 경로
   * @returns {RegExp} 정규식
   */
  _pathToRegex(path) {
    const pattern = path
      .replace(/\//g, '\\/')
