   * 경로에서 매개변수 이름 추출
   * @private
   * @param {string} path - 경로
   * @returns {string[]} 매개변수 이름 배열
   */
  _extractParamNames(path) {
    const matches = path.match(/:(\w+)/g) || [];
    return matches.map(m => m.slice(1));
