   * 라우트 매칭
   * @param {string} path - 경로
   * @returns {Object|null} 매칭된 라우트 정보
   */
  matchRoute(path) {
    for (const route of this.routes) {
      const match = route.regex.exec(path);
      if (match) {
        const params = {};
        route.params.forEach((param, index) => {
          params[param] = match[index + 1];
