  }

  /**
   * 쿼리 문자열 파싱
   * @private
   * @returns {Object} 쿼리 객체
   */
  _parseQuery() {
    const query = {};
    const params = new URLSearchParams(window.location.search);
    params.forEach((value, key) => {
      query[key] = value;
    });
    return query;
  }

